<?php $this->layout('default'); use Moves\Services\CmsSite; use Moves\Support\CmsView as V; $saved = CmsSite::seoRoutes(); ?>
<?php foreach (CmsSite::SEO_ROUTES as $path => $name): ?><details class="cms-card"<?= isset($saved[$path]) ? ' open' : '' ?>><summary><strong><?= V::e($name) ?></strong> <small><?= V::e($path) ?></small></summary><form method="post" action="/acao/seo-save"><?= V::csrf() ?><input type="hidden" name="route_path" value="<?= V::e($path) ?>"><?php $this->insert('components/seo-fields', ['seo' => $saved[$path] ?? [], 'prefix' => md5($path)]); ?><button class="cms-btn-primary">Salvar</button></form></details><?php endforeach; ?>
